const s=(a,t,n)=>a<t?t:a>n?n:a;export function spanFor(a,t){const n=s((a-.5)/.8,0,1);return t.narrowSpan+(t.wideSpan-t.narrowSpan)*n}export function distanceFor(a,t,n){const e=Math.atan(Math.tan(n*Math.PI/360)*t);return a/2/Math.tan(e)}export function cameraFor(a,t,n,e,c=null){let r=spanFor(a,t),x=n,h=e;if(c&&e){const o=Math.min(e.x,c.x)-t.includeMargin,m=Math.max(e.x,c.x)+t.includeMargin;r=s(m-o,r,t.maxSpan),h={x:(o+m)/2,z:e.z},x={minX:n.minX,maxX:Math.max(n.maxX,m)}}const i=distanceFor(r,a,t.fovDegrees),z=Math.hypot(t.height,t.back),M=t.height/z,f=t.back/z,y=Math.max(0,(x.maxX-x.minX)/2-r/2+1),p=(x.minX+x.maxX)/2;let u=t.target.x,g=t.target.z;if(h){u=s(h.x,p-y,p+y);const o=1-s((a-.5)/.8,0,1);g=t.target.z+(e.z-t.target.z)*.5*o}return{position:{x:u,y:t.target.y+M*i,z:g+f*i},target:{x:u,y:t.target.y,z:g},span:r,distance:i}}export function cameraOn(a,t,n,e){const c=distanceFor(e,t,n.fovDegrees),r=Math.hypot(n.height,n.back);return{position:{x:a.x,y:n.target.y+n.height/r*c,z:a.z+n.back/r*c},target:{x:a.x,y:n.target.y,z:a.z},span:e,distance:c}}export function rayToGround(a,t){if(t.y>=-1e-6)return null;const n=-a.y/t.y;return{x:a.x+t.x*n,z:a.z+t.z*n}}export function ease(a,t,n,e){return t+(a-t)*Math.exp(-n*e)}
